    "_%n resolved report_::_%n resolved reports_" : ["%n вырашаная скарга","%n вырашаныя скаргі","%n вырашаных скаргаў","%n вырашанай скаргі"],
    "Reported account" : "Уліковы запіс, на які скардзяцца",
    "Reporter" : "Аўтар скаргі",
